@extends('layouts.app')

@section('content')
    <div class="main scenes" id="fullpage">
        <section data-aos="scene" class="section scene scene-1 spy" id="scene-1">
            <div class="layers">
                <div id="parallax-layers">
                    <div data-depth="0" class="layer layer-back"></div>
                    <div data-depth="0.1" class="layer layer-main"></div>
                    <div data-depth="0.2" class="layer layer-clouds">
                        <div class="layer-cloud layer-cloud-left"></div>
                        <div class="layer-cloud layer-cloud-right"></div>
                    </div>
                    <div data-depth="0.2" class="layer layer-front"></div>
                    <div class="layer layer-overlay"></div>
                    <div data-depth="0.3" class="layer layer-text">
                        <div class="layer-text-small">
                            <p>{!! $variable->data['header_description'][app()->getLocale()]  !!}</p>
                        </div>
                        <div class="layer-text-big">
                            <p>{{ $variable->data['header_title'][app()->getLocale()] }}</p>
                        </div>
                    </div>
                    <div data-depth="0.3" class="layer layer-man"></div>
                </div>
            </div>
        </section>
        <section data-aos="scene" class="fp-section section scene scene-2 spy fp-auto-height" id="scene-2">
            <div class="half-img d-none d-md-flex">
                <img src="/images/content/scene-2-img.png">
            </div>

            <div class="container h-100">
                <div class="row h-100 align-items-center">
                    <div class="col-12 col col-lg-4 offset-lg-1 col-md-6">
                        <div class="scene-text">
                            <h2 class="scene-title">
                                {{ $variable->data['tenir_title'][app()->getLocale()] }}
                            </h2>

                            <p class="scene-desc">
                                {!! $variable->data['tenir_description'][app()->getLocale()]  !!}
                            </p>

                            <a href="{{ route('hotel.index') }}" class="scene-link">
                                {{ translate('uznat-bolshe') }}
                            </a>
                        </div>
                    </div>
                    <div class="col-12 col col-lg-4 offset-lg-2 col-md-6">
                        <div class="scene-map">
